1	package extproc
2	
3	import (
4		"encoding/json"
5		"strings"
6		"time"
7	
8		ext_proc "github.com/envoyproxy/go-control-plane/envoy/service/ext_proc/v3"
9	
10		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/inflight"
11		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/latency"
12		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
13		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
14	)
15	
16	func (r *OpenAIRouter) handleStreamingResponseBody(
17		responseBody []byte,
18		ctx *RequestContext,
19	) *ext_proc.ProcessingResponse {
20		recordStreamingTTFT(ctx)
21		ensureStreamingState(ctx)
22	
23		responseAPIStream := isResponseAPIRequest(ctx)
24		parseBody := responseBody
25		if responseAPIStream {
26			frames, remainder := reassembleSSEFrames(ctx.PendingSSEBytes, responseBody)
27			ctx.PendingSSEBytes = remainder
28			parseBody = frames
29		}
30	
31		chunk := string(parseBody)
32		if len(parseBody) > 0 {
33			ctx.HasStreamingChunks = true
34		}
35		r.parseStreamingChunk(chunk, ctx)
36	
37		streamDone := strings.Contains(chunk, "data: [DONE]")
38	
39		if responseAPIStream {
40			bodyMutation := r.buildResponseAPIStreamingBodyMutation(parseBody, ctx)
41			if streamDone {
42				r.finalizeStreamingResponse(ctx)
43			}
44			return buildResponseBodyContinueResponse(bodyMutation, responseAPIStreamingHeaderMutation())
45		}
46	
47		if streamDone {
48			r.finalizeStreamingResponse(ctx)
49		}
50	
51		return buildResponseBodyContinueResponse(nil, nil)
52	}
53	
54	func recordStreamingTTFT(ctx *RequestContext) {
55		if ctx == nil || ctx.TTFTRecorded || ctx.ProcessingStartTime.IsZero() || ctx.RequestModel == "" {
56			return
57		}
58	
59		ttft := time.Since(ctx.ProcessingStartTime).Seconds()
60		if ttft <= 0 {
61			return
62		}
63	
64		metrics.RecordModelTTFT(ctx.RequestModel, ttft)
65		ctx.TTFTSeconds = ttft
66		ctx.TTFTRecorded = true
67		latency.UpdateTTFT(ctx.RequestModel, ttft)
68		ctx.CacheWarmthEstimate = latency.EstimateCacheProbability(latency.CacheEstimationInput{
69			Model:       ctx.RequestModel,
70			TTFTSeconds: ttft,
71		})
72		maybeEmitTransitionEvent(ctx)
73		logging.Debugf("Recorded TTFT on first streamed body chunk: model=%q, TTFT=%.4fs", ctx.RequestModel, ttft)
74	}
75	
76	func ensureStreamingState(ctx *RequestContext) {
77		if ctx.StreamingMetadata == nil {
78			ctx.StreamingMetadata = make(map[string]interface{})
79		}
80		if ctx.StreamingToolCalls == nil {
81			ctx.StreamingToolCalls = make(map[int]*StreamingToolCallState)
82		}
83		if ctx.ResponseAPIStreamToolCallItemIDs == nil {
84			ctx.ResponseAPIStreamToolCallItemIDs = make(map[int]string)
85		}
86		if ctx.ResponseAPIStreamToolCallOutputIndex == nil {
87			ctx.ResponseAPIStreamToolCallOutputIndex = make(map[int]int)
88		}
89	}
90	
91	func (r *OpenAIRouter) finalizeStreamingResponse(ctx *RequestContext) {
92		// Idempotency guard: finalization records completion-latency metrics,
93		// ends the inflight token, and attaches the replay body — all of which
94		// must happen exactly once. The Anthropic-client streaming cell can
95		// reach this twice for one stream (the emitter's streamDone fires on
96		// one chunk, then a later terminal chunk still matches the
97		// "data: [DONE]" guard), so a second entry must be a no-op.
98		if ctx.StreamingComplete {
99			return
100		}
101		ctx.StreamingComplete = true
102		logging.ComponentDebugEvent("extproc", "streaming_response_finalized", map[string]interface{}{
103			"model":            ctx.RequestModel,
104			"attempting_cache": true,
105		})
106	
107		if ctx.RequestModel != "" && !ctx.StartTime.IsZero() {
108			completionLatency := time.Since(ctx.StartTime).Seconds()
109			metrics.RecordModelCompletionLatency(ctx.RequestModel, completionLatency)
110			logging.ComponentDebugEvent("extproc", "streaming_completion_latency_recorded", map[string]interface{}{
111				"model":                 ctx.RequestModel,
112				"completion_latency_ms": time.Since(ctx.StartTime).Milliseconds(),
113			})
114		}
115	
116		inflight.End(ctx.RequestModel, ctx.InflightToken)
117		ctx.InflightToken = 0
118	
