123		usage := extractStreamingUsage(ctx)
124		reconstructedJSON, err := buildReconstructedStreamingResponse(ctx, usage, false)
125		if err != nil {
126			if errors.Is(err, errSkipStreamingCache) {
127				return nil
128			}
129			return err
130		}
