135	func validateStreamingCachePreconditions(ctx *RequestContext) error {
136		switch {
137		case !ctx.StreamingComplete:
138			logging.Warnf("Stream not completed (no [DONE] marker), skipping cache")
139		case ctx.StreamingAborted:
140			logging.Warnf("Stream was aborted, skipping cache")
141		case ctx.StreamingContent == "":
142			logging.Warnf("Streaming response has no content, skipping cache")
143		case ctx.StreamingMetadata["id"] == nil || ctx.StreamingMetadata["model"] == nil:
144			logging.Warnf("Streaming response missing required metadata, skipping cache")
145		default:
146			return nil
147		}
148		return errSkipStreamingCache
149	}
