151	var errSkipStreamingCache = &streamingCacheSkipError{}
152	
153	type streamingCacheSkipError struct{}
154	
155	func (e *streamingCacheSkipError) Error() string { return "skip streaming cache" }
156	
157	func buildReconstructedStreamingResponse(
158		ctx *RequestContext,
159		usage openai.CompletionUsage,
160		includeToolCalls bool,
161	) ([]byte, error) {
162		if ctx == nil {
163			return nil, errSkipStreamingCache
164		}
165	
166		id, idOK := ctx.StreamingMetadata["id"].(string)
167		model, modelOK := ctx.StreamingMetadata["model"].(string)
168		created, createdOK := ctx.StreamingMetadata["created"].(int64)
169		if !idOK || !modelOK || !createdOK {
170			logging.Warnf("Streaming response missing metadata required for reconstruction, skipping")
171			return nil, errSkipStreamingCache
172		}
173	
174		finishReason := "stop"
175		if finishReasonValue, ok := ctx.StreamingMetadata["finish_reason"].(string); ok && finishReasonValue != "" {
176			finishReason = finishReasonValue
177		}
178	
179		message := map[string]interface{}{
180			"role": "assistant",
181		}
182		if ctx.StreamingContent != "" {
183			message["content"] = ctx.StreamingContent
184		} else {
185			message["content"] = nil
186		}
187		// Preserve reasoning so a cache hit returns the same reasoning_content the
188		// live stream delivered (reasoning models stream it under delta.reasoning_content).
189		if ctx.StreamingReasoning != "" {
190			message["reasoning_content"] = ctx.StreamingReasoning
191		}
192	
193		toolCalls := buildStreamingResponseToolCalls(ctx)
194		if includeToolCalls && len(toolCalls) > 0 {
195			message["tool_calls"] = toolCalls
196			if finishReason == "stop" {
197				finishReason = "tool_calls"
198			}
199		}
200	
201		if ctx.StreamingContent == "" && (!includeToolCalls || len(toolCalls) == 0) {
202			logging.Warnf("Reconstructed response has no valid assistant payload, skipping cache")
203			return nil, errSkipStreamingCache
204		}
205	
206		reconstructed := map[string]interface{}{
207			"id":      id,
208			"object":  "chat.completion",
209			"created": created,
210			"model":   model,
211			"choices": []map[string]interface{}{
212				{
213					"index":         0,
214					"message":       message,
215					"finish_reason": finishReason,
216				},
217			},
218			"usage": map[string]interface{}{
219				"prompt_tokens":     usage.PromptTokens,
220				"completion_tokens": usage.CompletionTokens,
221				"total_tokens":      usage.TotalTokens,
222			},
223		}
224	
225		reconstructedJSON, err := json.Marshal(reconstructed)
226		if err != nil {
227			logging.Errorf("Failed to marshal reconstructed response: %v", err)
228			return nil, err
229		}
230		return reconstructedJSON, nil
231	}
