233	func buildStreamingResponseToolCalls(ctx *RequestContext) []map[string]interface{} {
234		if ctx == nil || len(ctx.StreamingToolCalls) == 0 {
235			return nil
236		}
237	
238		indexes := make([]int, 0, len(ctx.StreamingToolCalls))
239		for index := range ctx.StreamingToolCalls {
240			indexes = append(indexes, index)
241		}
242		sort.Ints(indexes)
243	
244		toolCalls := make([]map[string]interface{}, 0, len(indexes))
245		for _, index := range indexes {
246			call := ctx.StreamingToolCalls[index]
247			if call == nil || (call.ID == "" && call.Name == "" && call.Arguments == "") {
248				continue
249			}
250			toolCalls = append(toolCalls, map[string]interface{}{
251				"id":   call.ID,
252				"type": "function",
253				"function": map[string]interface{}{
254					"name":      call.Name,
255					"arguments": call.Arguments,
256				},
257			})
258		}
259		return toolCalls
260	}
