267			return nil
268		}
269	
270		ttlSeconds := -1
271		if r != nil && r.Config != nil {
272			ttlSeconds = r.Config.GetCacheTTLSecondsForDecisionObject(ctx.VSRSelectedDecision)
273		}
274		// Retention ttl_turns (when set) overrides the decision/global default for
275		// the reconstructed streaming entry, mirroring the non-streaming path.
276		ttlSeconds = applyRetentionTTLOverride(ttlSeconds, ctx)
277	
278		if ctx.RequestID == "" {
279			logging.Warnf("No request ID available, cannot cache streaming response")
280			return nil
281		}
282	
283		// Must finalize in place (by request_id) like the non-streaming path.
284		// AddEntry would mint a new key and orphan the empty pending entry,
285		// which then shadows KNN lookups and causes cache misses (issue #2030).
286		return r.updateStreamingCacheEntry(ctx.RequestID, reconstructedJSON, ttlSeconds)
287	}
