293	) error {
294		if err := r.Cache.UpdateWithResponse(requestID, reconstructedJSON, ttlSeconds); err != nil {
295			logging.Errorf("Cache update failed for streaming %s: %v", requestID, err)
296			return err
297		}
298		return nil
299	}
